package dev.alien.client.smoke;
import dev.alien.client.AlienClient;import dev.alien.client.config.ClientConfig;import dev.alien.client.effects.ghost.*;
import java.io.*;import java.nio.file.Files;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import java.util.*;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.entity.*;import net.minecraft.entity.monster.EntityZombie;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.init.*;import net.minecraft.item.ItemStack;import net.minecraft.nbt.NBTTagCompound;import net.minecraft.util.*;import net.minecraft.world.*;
import net.minecraftforge.fml.common.*;import net.minecraftforge.fml.common.event.*;import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;import net.minecraftforge.fml.common.gameevent.TickEvent;import org.lwjgl.opengl.*;
@Mod(modid="alien_ghost_smoke",name="Ghost elimination real render validation",version="1",clientSideOnly=true,dependencies="required-after:alienclient")
public final class AlienGhostSmoke {
 private Minecraft m;private File out;private int stage,target,sequence;private long start,since,kills,draws;private boolean done;private final List<String> checks=new ArrayList<String>();private final Set<Integer> phases=new HashSet<Integer>();private long sampleAt;private final List<Long> times=new ArrayList<Long>();
 private ClientConfig c(){return AlienClient.get().config();}
 @Mod.EventHandler public void init(FMLInitializationEvent e)throws Exception{if(!Boolean.getBoolean("alien.ghost.smoke"))return;m=Minecraft.getMinecraft();out=new File(System.getProperty("alien.ghost.smoke.output"));Files.createDirectories(out.toPath());Files.deleteIfExists(new File(out,"result.txt").toPath());AlienClient.get().store().resetDefaults();start=since=System.nanoTime();FMLCommonHandler.instance().bus().register(this);}
 private long elapsed(long t){return (System.nanoTime()-t)/1000000;}
 private void next(){stage++;since=System.nanoTime();System.out.println("ALIEN_GHOST_STAGE "+stage);}
 private void check(boolean b,String s){if(!b)throw new AssertionError(s);checks.add(s);System.out.println("ALIEN_GHOST_CHECK "+s);}
 private void server(Runnable r)throws Exception{m.getIntegratedServer().addScheduledTask(r).get();}
 private EntityPlayerMP player(){return m.getIntegratedServer().getConfigurationManager().playerEntityList.get(0);}
 private void target()throws Exception{server(()->{EntityZombie z=new EntityZombie(player().worldObj);NBTTagCompound tag=new NBTTagCompound();z.writeToNBT(tag);tag.setBoolean("NoAI",true);tag.setBoolean("Silent",true);z.readFromNBT(tag);z.setPosition(.5,4,.5);z.setHealth(1);z.setCustomNameTag("ALIEN GHOST TEST");z.setAlwaysRenderNameTag(true);z.setCurrentItemOrArmor(4,new ItemStack(Items.diamond_helmet));player().worldObj.spawnEntityInWorld(z);target=z.getEntityId();});}
 private void attack()throws Exception{Entity e=m.theWorld.getEntityByID(target);check(e instanceof EntityLivingBase,"Actual integrated-server target is tracked by the client");m.playerController.attackEntity(m.thePlayer,e);m.thePlayer.swingItem();}
 @SubscribeEvent public void render(TickEvent.RenderTickEvent e){if(done||e.phase!=TickEvent.Phase.END)return;try{if(elapsed(start)>210000)throw new AssertionError("Deadline stage "+stage);if(stage==3){motion();return;}if(elapsed(since)<800)return;step();}catch(Throwable f){done=true;write(false,f);m.shutdown();throw new RuntimeException(f);}}
 private void capture(String name)throws Exception{if(Boolean.getBoolean("alien.ghost.video"))return;File f=new File(out,"screenshots/"+name+".png");Files.deleteIfExists(f.toPath());ScreenShotHelper.saveScreenshot(out,name+".png",m.displayWidth,m.displayHeight,m.getFramebuffer());BufferedImage im=ImageIO.read(f);check(im!=null&&im.getWidth()==1280&&im.getHeight()==720,"Original Forge framebuffer "+name);check(GL11.glGetError()==GL11.GL_NO_ERROR,"No GL error after "+name);}
 private void visibleFinale()throws Exception{
  if(Boolean.getBoolean("alien.ghost.video"))return;
  BufferedImage stars=ImageIO.read(new File(out,"screenshots/13-ghost-constellation-finale.png")),clean=ImageIO.read(new File(out,"screenshots/07-ghost-clean-after-effect.png"));int luminous=0;Set<Integer> regions=new HashSet<Integer>();
  for(int y=50;y<340;y++)for(int x=380;x<870;x++){int a=stars.getRGB(x,y),b=clean.getRGB(x,y);if((a>>8&255)-(b>>8&255)>30){luminous++;regions.add(x/35);}}
  check(luminous>120&&regions.size()>=4,"Constellation creates visible luminous pixels across multiple sky regions after the body has gone");
 }
 private void motion()throws Exception{
  if(GhostManager.confirmed()==kills){if(elapsed(since)>7000)throw new AssertionError("Real sword kill was not confirmed");return;}
  float age=GhostManager.oldestAge();
  if(age>=0&&sequence<48&&System.nanoTime()-sampleAt>45000000L){capture(String.format(Locale.ROOT,"ghost-motion-%02d",sequence++));sampleAt=System.nanoTime();times.add(elapsed(start));}
  for(int i=0;i<7;i++)if(age>=new float[]{.25f,.65f,1.15f,1.75f,2.25f,2.85f,3.30f}[i]&&phases.add(i))capture(new String[]{"02-ghost-detaching","03-ghost-ascending","04-ghost-floating","05-ghost-dissolving","06-ghost-final-sparks","12-ghost-constellation-forming","13-ghost-constellation-finale"}[i]);
  if(GhostManager.active()==0&&sequence>0){check(GhostManager.confirmed()==kills+1,"A real vanilla sword action causes exactly one confirmed elimination effect");check(GhostRenderer.finales()>0,"Constellation is actually rendered after body dissolution");check(GhostMaterial.ready(),"Pearl lighting shader compiles and links in actual Forge GL");check(GhostManager.rendered()>draws,"Ghost geometry reaches actual world rendering");check(phases.size()==7&&sequence>=8,"Detach, ascent, dissolution and constellation finale produce multiple actual motion frames");try(PrintWriter w=new PrintWriter(new File(out,"ghost-motion-times.txt"))){for(long t:times)w.println(t);}next();}
 }
 private void step()throws Exception{
  switch(stage){
   case 0:if(m.currentScreen==null)return;check(!c().killEffects.enabled,"Old profiles keep the new effect disabled");boolean video=Boolean.getBoolean("alien.ghost.video");int nativeW=video?960:1280,nativeH=video?540:720;Display.setDisplayMode(new DisplayMode(nativeW,nativeH));Display.setLocation(0,0);java.lang.reflect.Method resize=Minecraft.class.getDeclaredMethod("resize",int.class,int.class);resize.setAccessible(true);resize.invoke(m,nativeW,nativeH);m.gameSettings.guiScale=2;m.gameSettings.limitFramerate=60;m.gameSettings.renderDistanceChunks=3;m.gameSettings.pauseOnLostFocus=false;m.launchIntegratedServer("AlienGhost-"+System.currentTimeMillis(),"Disposable ghost validation",new WorldSettings(42,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT));next();return;
   case 1:if(m.thePlayer==null||m.thePlayer.ticksExisted<40)return;m.displayGuiScreen(null);c().hud.applyPreset("Cinematic");c().cosmetics.enabled=false;c().effects.enabled=false;c().killEffects.enabled=true;m.gameSettings.fovSetting=80;server(()->{EntityPlayerMP p=player();p.worldObj.getGameRules().setOrCreateGameRule("doMobSpawning","false");p.worldObj.getGameRules().setOrCreateGameRule("doDaylightCycle","false");p.worldObj.setWorldTime(13200);p.setPositionAndUpdate(.5,4,-2.3);p.inventory.mainInventory[0]=new ItemStack(Items.diamond_sword);p.inventory.currentItem=0;p.inventoryContainer.detectAndSendChanges();});m.thePlayer.rotationYaw=0;m.thePlayer.rotationPitch=-16;target();next();return;
   case 2:if(m.theWorld.getEntityByID(target)==null)return;capture("01-ghost-target-alive");check(GhostManager.active()==0,"A living target never creates an elimination ghost");kills=GhostManager.confirmed();draws=GhostManager.rendered();attack();next();return;
   case 4:check(GhostManager.active()==0,"Ghost expires and releases its transient state");capture("07-ghost-clean-after-effect");visibleFinale();target();next();return;
   case 5:server(()->{EntityLivingBase e=(EntityLivingBase)player().worldObj.getEntityByID(target);e.attackEntityFrom(DamageSource.fall,100);});next();return;
   case 6:check(GhostManager.confirmed()==kills+1&&GhostManager.active()==0,"Environmental death does not create a player elimination effect");target();c().killEffects.mobs=false;next();return;
   case 7:attack();next();return;
   case 8:check(GhostManager.confirmed()==kills+1,"Mob filter rejects an otherwise real own kill");c().killEffects.mobs=true;c().killEffects.enabled=false;target();next();return;
   case 9:attack();next();return;
   case 10:check(GhostManager.confirmed()==kills+1&&GhostManager.active()==0,"Disabled effect does not record or render an elimination");c().killEffects.enabled=true;m.displayGuiScreen(new GhostStudioScreen(null));next();return;
   case 11:capture("08-ghost-studio-neon");click(11);check("Spectral".equals(c().killEffects.preset),"Palette button changes real ghost colors");next();return;
   case 12:capture("09-ghost-studio-spectral");System.setProperty("alien.ghost.fallback","true");click(11);click(16);check(c().killEffects.calm,"Calm control changes the real motion design");next();return;
   case 13:capture("10-ghost-studio-rose");capture("14-ghost-studio-cpu-fallback");System.clearProperty("alien.ghost.fallback");AlienClient.get().store().saveProfile("ghost-smoke");c().killEffects.duration=1.5f;c().killEffects.enabled=false;check(AlienClient.get().store().loadProfile("ghost-smoke"),"Unified ghost profile reload succeeds");check(c().killEffects.constellation,"Constellation preference survives the Unified profile");check(c().killEffects.enabled&&c().killEffects.calm&&"Rose".equals(c().killEffects.preset),"Ghost palette, enabled state and calm motion persist together");check(GhostManager.confirmed()==kills+1,"Animated studio preview never counts as a real elimination");click(2);target();next();return;
   case 14:kills=GhostManager.confirmed();attack();next();return;
   case 15:check(GhostManager.confirmed()==kills+1&&GhostManager.active()==1,"A new real kill works after returning from profile and editor");capture("11-ghost-rose-calm-world");c().killEffects.enabled=false;next();return;
   case 16:check(GhostManager.active()==0,"Turning the effect off clears active geometry immediately");m.loadWorld(null);m.displayGuiScreen(new GuiMainMenu());next();return;
   case 17:check(GhostManager.active()==0,"Leaving the world clears all pending and active effects");done=true;write(true,null);m.shutdown();return;
  }
 }
 private void click(int id)throws Exception{java.lang.reflect.Field f=GuiScreen.class.getDeclaredField("buttonList");f.setAccessible(true);for(Object o:(List<?>)f.get(m.currentScreen)){GuiButton b=(GuiButton)o;if(b.id==id){java.lang.reflect.Method a=GhostStudioScreen.class.getDeclaredMethod("actionPerformed",GuiButton.class);a.setAccessible(true);a.invoke(m.currentScreen,b);return;}}throw new AssertionError("Missing ghost button "+id);}
 private void write(boolean pass,Throwable failure){try(PrintWriter w=new PrintWriter(new File(out,"result.txt"),"UTF-8")){w.println((pass?"PASS ":"FAIL stage "+stage+" ")+checks.size()+" checks");w.println("Actual Forge 1.8.9 / Linux software OpenGL / real integrated-server kills of labeled test zombies. Studio shots are labeled live previews. No external multiplayer test.");for(String s:checks)w.println("PASS "+s);if(failure!=null)failure.printStackTrace(w);}catch(Exception ignored){}}
}
